package com.app.bharatphoton.awsUtilsimport android.content.Contextimport android.graphics.Bitmapimport android.graphics.Matriximport android.media.ExifInterfaceimport com.amazonaws.auth.BasicAWSCredentialsimport com.amazonaws.mobileconnectors.s3.transferutility.TransferListenerimport com.amazonaws.mobileconnectors.s3.transferutility.TransferStateimport com.amazonaws.mobileconnectors.s3.transferutility.TransferUtilityimport com.amazonaws.regions.Regionimport com.amazonaws.services.s3.AmazonS3Clientimport java.io.Fileimport java.io.FileOutputStream@Suppress("DEPRECATION")class UploadToAws(val awsAccessKey: String, val awsBucketName: String, val awsSecretKey: String, val context: Context, val region: String) {    fun uploadFile(file: File, onSuccess: (url: String) -> Unit, onError: (error: String) -> Unit, onProgress: (progress: Int) -> Unit) {        val fileName = file.name        val fileExtension = file.extension        val keyName = if (fileName.endsWith(".$fileExtension")) fileName else "$fileName.$fileExtension"        val credential = BasicAWSCredentials(awsAccessKey, awsSecretKey)        val s3Client = AmazonS3Client(credential)        s3Client.setRegion(Region.getRegion(region))        val transferUtility = TransferUtility.builder().s3Client(s3Client).context(context).build()        val uploadObserver = transferUtility.upload(awsBucketName, fileName, file)        uploadObserver.setTransferListener(object : TransferListener {            override fun onStateChanged(id: Int, state: TransferState?) {                when (state) {                    TransferState.COMPLETED -> {                        val url = s3Client.getUrl(awsBucketName, keyName).toString()                        onSuccess(url)                    }                    TransferState.FAILED -> {                        onError("Failed")                    }                    TransferState.WAITING_FOR_NETWORK -> {                    }                    else -> {                    }                }            }            override fun onProgressChanged(id: Int, bytesCurrent: Long, bytesTotal: Long) {                val progress = (bytesCurrent.toFloat() / bytesTotal * 100).toInt()                onProgress(progress)            }            override fun onError(id: Int, ex: java.lang.Exception?) {                onError(ex?.message.toString())            }        })    }    companion object {        fun imageBitmapToFile(context: Context, bitmap: Bitmap): File? {            val randomFileName = System.currentTimeMillis().toString()            val file = File(context.cacheDir, "$randomFileName.jpg")            try {                val tempFile = File(context.cacheDir, "temp_${randomFileName}.jpg")                FileOutputStream(tempFile).use { out ->                    bitmap.compress(Bitmap.CompressFormat.JPEG, 100, out)                }                val exif = ExifInterface(tempFile.absolutePath)                val orientation = exif.getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL)                val correctedBitmap = correctImageRotation(bitmap, orientation)                file.outputStream().use {                    correctedBitmap.compress(Bitmap.CompressFormat.JPEG, 100, it)                    it.flush()                    it.close()                }                tempFile.delete()                return file            } catch (e: Exception) {                e.printStackTrace()            }            return null        }        private fun correctImageRotation(bitmap: Bitmap, orientation: Int): Bitmap {            val matrix = Matrix()            when (orientation) {                ExifInterface.ORIENTATION_ROTATE_90 -> matrix.postRotate(90f)                ExifInterface.ORIENTATION_ROTATE_180 -> matrix.postRotate(180f)                ExifInterface.ORIENTATION_ROTATE_270 -> matrix.postRotate(270f)            }            return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)        }    }}